// ── KMP: Build Failure Function (lps array) — O(m) ─────────────
function buildLPS(pattern) {
  const m = pattern.length;
  const lps = new Array(m).fill(0);
  // lps[0] is always 0 — no proper prefix for a single character
  let len = 0; // length of the current longest prefix-suffix
  let i = 1;

  while (i < m) {
    if (pattern[i] === pattern[len]) {
      // Case 1: extend the current prefix-suffix
      lps[i] = ++len;
      i++;
    } else if (len > 0) {
      // Case 2: fall back to next shorter prefix-suffix
      // Do NOT increment i — try again with shorter prefix
      len = lps[len - 1];
    } else {
      // Case 3: no prefix-suffix possible at position i
      lps[i] = 0;
      i++;
    }
  }
  return lps;
}

// ── KMP: Search Phase — O(n) ───────────────────────────────────
function kmpSearch(text, pattern) {
  const n = text.length, m = pattern.length;
  if (m === 0) return [];
  const lps = buildLPS(pattern);
  const matches = [];
  let i = 0; // text index — ONLY moves forward
  let j = 0; // pattern index — can reset via lps

  while (i < n) {
    if (text[i] === pattern[j]) {
      i++;
      j++;
    }
    if (j === m) {
      // Full match found at text index (i - j)
      matches.push(i - j);
      // Use lps to continue searching (handles overlapping matches)
      j = lps[j - 1];
    } else if (i < n && text[i] !== pattern[j]) {
      if (j > 0) {
        j = lps[j - 1]; // fall back without moving i
      } else {
        i++; // no prefix to fall back to, advance text
      }
    }
  }
  return matches;
}

// ── Worked Example ──────────────────────────────────────────────
const text = "ABABDABACDABABCABAB";
const pattern = "ABABCABAB";

const lps = buildLPS(pattern);
console.log("LPS array:", lps);
// pattern: A B A B C A B A B
// lps:   [ 0,0,1,2,0,1,2,3,4 ]
// lps[8]=4 means 'ABABCABAB' has 'ABAB' as longest prefix=suffix

const result = kmpSearch(text, pattern);
console.log("Matches at indices:", result);
// Matches at indices: [10]
// text[10..18] = 'ABABCABAB' — verified!

// Test overlapping matches:
console.log(kmpSearch("AAAA", "AA")); // [0, 1, 2]
// At index 0: AA matches
// After match, j = lps[1] = 1 (not 0!), so next search starts
// with one 'A' already matched — correctly finds overlap at index 1

// ── Rabin-Karp Rolling Hash — O(n+m) expected ─────────────────
function rabinKarp(text, pattern) {
  const n = text.length, m = pattern.length;
  const BASE = 31;          // base for polynomial hash
  const MOD = 1_000_000_007; // large prime to reduce collisions
  const matches = [];
  if (m > n) return matches;

  // Precompute BASE^(m-1) mod MOD  — needed to remove leftmost char
  let highPow = 1;
  for (let k = 0; k < m - 1; k++) {
    highPow = (highPow * BASE) % MOD;
  }

  // Map characters to numbers: 'a'=1, 'b'=2, ...
  // Using 1-indexed avoids leading zeros masking different strings
  const charCode = c => c.charCodeAt(0) - 96;

  // Compute initial hashes for pattern and first window
  let patHash = 0, winHash = 0;
  for (let k = 0; k < m; k++) {
    patHash = (patHash * BASE + charCode(pattern[k])) % MOD;
    winHash = (winHash * BASE + charCode(text[k])) % MOD;
  }

  // Slide the window across the text
  for (let i = 0; i <= n - m; i++) {
    if (winHash === patHash) {
      // Hash match: verify with direct comparison to avoid false positives
      if (text.substring(i, i + m) === pattern) {
        matches.push(i);
      }
    }
    // Roll the hash: remove text[i], add text[i + m]
    if (i < n - m) {
      // Step 1: remove leftmost character's contribution
      winHash = (winHash - charCode(text[i]) * highPow % MOD + MOD) % MOD;
      // Step 2: shift left by multiplying by BASE, add new rightmost char
      winHash = (winHash * BASE + charCode(text[i + m])) % MOD;
    }
  }
  return matches;
}

// ── Test cases ─────────────────────────────────────────────────
console.log(rabinKarp("abcababcabc", "abc"));
// [0, 5, 8] — three occurrences

console.log(rabinKarp("aaaaaa", "aa"));
// [0, 1, 2, 3, 4] — overlapping matches work correctly

// ── Multi-pattern extension (conceptual) ───────────────────────
function rabinKarpMulti(text, patterns) {
  const m = patterns[0].length; // assume same length for simplicity
  const BASE = 31, MOD = 1_000_000_007;
  // Build a Set of all pattern hashes O(k*m)
  const patHashes = new Map(); // hash -> pattern for verification
  for (const p of patterns) {
    let h = 0;
    for (const c of p) h = (h * BASE + c.charCodeAt(0) - 96) % MOD;
    patHashes.set(h, p);
  }
  // Now one O(n) pass finds any of the k patterns
  // (details omitted for brevity — same rolling hash loop)
  return patHashes; // placeholder
}
